    private static Integer boundedInt(TextField field,int min,int max){try{int value=Integer.parseInt(field.getText().trim());return value>=min&&value<=max?value:null;}catch(Exception ignored){return null;}}
    private static Double boundedDouble(TextField field,double minExclusive,double max){try{double value=Double.parseDouble(field.getText().trim());return Double.isFinite(value)&&value>minExclusive&&value<=max?value:null;}catch(Exception ignored){return null;}}
